// src/client/routes.ts
var STATUS_ROUTE = "api/git-tree/status";
var WORKSPACES_ROUTE = "api/git-tree/workspaces";
var DIFF_ROUTE = "api/git-tree/diff";
var REFS_ROUTE = "api/git-tree/refs";
