var STAGE_ROUTE = "api/git-tree/stage";
var UNSTAGE_ROUTE = "api/git-tree/unstage";
var COMMIT_ROUTE = "api/git-tree/commit";
var OPEN_ROUTE = "api/git-tree/open";
