var COMMIT_MESSAGE_ROUTE = "api/git-tree/commit-message";
function query(params) {
  const search = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) if (value !== void 0 && value !== "") search.set(key, value);
  const text = search.toString();
  return text === "" ? "" : "?" + text;
}
async function getJson(route, params, signal) {
  const response = await fetch(route + query(params), {
    signal,
    headers: { accept: "application/json" }
  });
  const payload = await response.json();
  return payload;
}
async function postJson(route, body, signal) {
  const response = await fetch(route, {
    method: "POST",
    signal,
    headers: { accept: "application/json", "content-type": "application/json" },
    body: JSON.stringify(body)
  });
  return await response.json();
}
function fetchWorkspaces(signal) {
  return getJson(WORKSPACES_ROUTE, {}, signal);
}
function fetchStatus(cwd, signal) {
  return getJson(STATUS_ROUTE, { cwd }, signal);
}
function fetchDiff(params, signal) {
  return getJson(DIFF_ROUTE, params, signal);
}
function fetchRefs(cwd, signal) {
  return getJson(REFS_ROUTE, { cwd }, signal);
}
function fetchCommitInfo(params, signal) {
  return getJson(COMMIT_INFO_ROUTE, params, signal);
}
function fetchHistory(params, signal) {
  return getJson(HISTORY_ROUTE, params, signal);
}
function pushBranch(cwd) {
  return postJson(PUSH_ROUTE + query({ cwd }), {});
}
function mergeBranch(branch, cwd) {
  return postJson(MERGE_ROUTE + query({ cwd }), { branch });
}
function discardPaths(paths, side, cwd) {
  return postJson(DISCARD_ROUTE + query({ cwd }), { paths, side });
}
function removePaths(paths, untracked, cwd) {
  return postJson(REMOVE_ROUTE + query({ cwd }), { paths, untracked });
}
function checkoutBranch(branch, cwd) {
  return postJson(CHECKOUT_ROUTE + query({ cwd }), { branch });
}
function createBranch(name, cwd, start) {
  return postJson(BRANCH_CREATE_ROUTE + query({ cwd }), { name, start });
}
function renameBranch(from, to, cwd) {
  return postJson(BRANCH_RENAME_ROUTE + query({ cwd }), { from, to });
}
function deleteBranch(name, cwd) {
  return postJson(BRANCH_DELETE_ROUTE + query({ cwd }), { name });
}
function stagePaths(paths, cwd) {
  return postJson(STAGE_ROUTE + query({ cwd }), { paths });
}
function unstagePaths(paths, cwd) {
  return postJson(UNSTAGE_ROUTE + query({ cwd }), { paths });
}
function commitChanges(message, cwd) {
  return postJson(COMMIT_ROUTE + query({ cwd }), { message });
}
function openLocal(target, cwd) {
  return postJson(OPEN_ROUTE + query({ cwd }), { target });
}
function fetchAiModels(signal) {
  return getJson(AI_MODELS_ROUTE, {}, signal);
}
function saveAiModel(provider, model) {
  return postJson(AI_MODEL_ROUTE, { provider, model });
}
function generateCommitMessage(input, cwd) {
  return postJson(COMMIT_MESSAGE_ROUTE + query({ cwd }), input);
}

// src/client/model.ts
function lastSegment(path) {
  const parts = String(path).split(/[\\/]+/).filter(Boolean);
  return parts.length > 0 ? parts[parts.length - 1] : path;
}
function splitPath(path) {
  const parts = String(path).split("/");
  const name = parts.pop() ?? path;
  return { dir: parts.length > 0 ? parts.join("/") + "/" : "", name };
}
function rowKey(path, side) {
  return side + "\0" + path;
}
function splitEntries(entries) {
  const staged = [];
  const unstaged = [];
  const conflicted = [];
  for (const entry of entries) {
    if (entry.conflicted) {
      conflicted.push(entry);
      continue;
    }
    if (entry.staged) staged.push(entry);
    if (entry.unstaged) unstaged.push(entry);
  }
  return { staged, unstaged, conflicted };
}
function statusLetter(entry, side) {
  if (side === "conflicted" || entry.conflicted) return "U";
  if (entry.kind === "untracked") return "?";
  if (entry.kind === "renamed") return "R";
  if (entry.kind === "copied") return "C";
  const letter = side === "staged" ? entry.x : entry.y;
  return letter && letter !== "." ? letter : "M";
}
function statusTone(letter) {
  if (letter === "A") return "ok";
  if (letter === "D" || letter === "U") return "error";
  if (letter === "M") return "warn";
  if (letter === "R" || letter === "C") return "accent";
  return "muted";
}
function sideFor(entry, side) {
  return side === "staged" ? "staged" : "unstaged";
}

